INSERT INTO "Lesson" ("id", "courseId", "title", "description", "videoUrl", "durationMin", "order") VALUES ('cmwb08gmz001poufn1v5227ox', 'cmwb08gmx001joufne95wppdm', 'Operaciones y stock a escala', 'Inventario, proveedores y tiempos sin romper la promesa.', 'https://storage.googleapis.com/gtv-videos-bucket/sample/Sintel.mp4', 16, 3);
INSERT INTO "Lesson" ("id", "courseId", "title", "description", "videoUrl", "durationMin", "order") VALUES ('cmwb08gmz001roufn1xgi81ga', 'cmwb08gmx001joufne95wppdm', 'Fidelización y LTV', 'Venderle de nuevo a quien ya te compró: el activo olvidado.', 'https://storage.googleapis.com/gtv-videos-bucket/sample/TearsOfSteel.mp4', 15, 4);
INSERT INTO "Lesson" ("id", "courseId", "title", "description", "videoUrl", "durationMin", "order") VALUES ('cmwb08gn0001toufnzeoubx90', 'cmwb08gmx001joufne95wppdm', 'Plan de crecimiento', 'Tu roadmap de 12 meses hacia la siguiente cifra.', 'https://storage.googleapis.com/gtv-videos-bucket/sample/ForBiggerEscapes.mp4', 20, 5);
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwb08gnk002toufnhk1gk7yc', 'cmwb08gn80021oufnncfddahr', 'El programa de Escalado a 7 Cifras me voló la cabeza. Números reales, ejemplos reales, cero humo. Recomendado para cualquiera que ya venda y quiera montar sistemas en vez de vivir apagando incendios. Lo estoy viendo por segunda vez y tomando notas distintas.', NULL, '2026-11-05T18:09:27.631+00:00', '2026-11-10T18:09:27.632+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwb08gnj002roufn4hmmm1r4', 'cmwb08gn2001voufn9di6pipr', 'Pregunta rápida para los que venden en Latam: qué pasarela están usando? Estoy evaluando cambiar porque los retrasos de liquidación me complican el flujo de caja para comprar inventario. Experiencias reales, por favor.', NULL, '2026-11-06T14:09:27.631+00:00', '2026-11-10T18:09:27.631+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwb08gnj002poufnumcl8hsy', 'cmwb08gn90022oufnt8rfwd8n', 'Primera comisión de afiliado: $47 dólares. Para muchos es poco; para mí es la prueba de que el modelo funciona. El orgullo no me deja dormir. La racha sigue, siguiente meta: la primera comisión recurrente de la semana.', NULL, '2026-11-07T05:09:27.630+00:00', '2026-11-10T18:09:27.631+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwb08gni002noufn0vfm51v7', 'cmwb08gn90023oufnf3rmtz88', 'Me acabo de crear la cuenta y completé mi perfil. Qué emoción empezar de cero con ustedes. Recomendación: por dónde empiezo, primero el programa de ecommerce o mejor el de contenidos? Mi objetivo es entender el mapa completo antes de elegir.', NULL, '2026-11-07T17:09:27.630+00:00', '2026-11-10T18:09:27.631+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwb08gnh002loufnmy87at5q', 'cmwb08gna0024oufnceq7kuic', 'Vengo del mundo físico, tengo un restaurante, y entré al hub para digitalizar el negocio. La primera lección de Ecommerce desde Cero me despejó dudas que arrastraba hace meses. Alguien más dando el salto de lo tradicional a lo digital?', NULL, '2026-11-08T04:09:27.629+00:00', '2026-11-10T18:09:27.630+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwb08gnh002joufnlqshc71b', 'cmwb08gn70020oufny97e8zxr', 'Mi compromiso del trimestre, por escrito y frente a testigos: 10.000 seguidores y 3 clientes de branding. Voy a publicar mi avance cada lunes en este muro para no perderme. Quien quiera, me acompaña y me exige cuando toque.', NULL, '2026-11-08T15:09:27.629+00:00', '2026-11-10T18:09:27.629+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwb08gng002houfnbh75r378', 'cmwb08gn5001youfn2n12eo7f', 'Día 12 probando el producto que elegí para mi dropsi. Primera venta a las 6:40 de la mañana. Una sola. Y la celebré como si fueran mil. Así se empieza, ¿verdad? Alguien más en etapa de validación para compartir números sin filtros?', NULL, '2026-11-08T22:09:27.628+00:00', '2026-11-10T18:09:27.628+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwb08gnf002foufnmyq8rzs0', 'cmwb08gn6001zoufn0agonm50', 'Les comparto un mini marco de copy que me está funcionando en emails: 1) dolor real, 2) promesa concreta, 3) prueba, 4) una sola llamada a la acción. Mi último email abrió al 41%. El CopyLab IA me ayuda a generar variantes en segundos y después las pulo a mano. Aliado silencioso.', NULL, '2026-11-09T12:09:27.627+00:00', '2026-11-10T18:09:27.628+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwb08gnf002doufne4c6ftat', 'cmwb08gn80021oufnncfddahr', 'Herramienta del día: usé la Calculadora de Precios antes de lanzar mi nueva línea de serums y descubrí que estaba dejando 23% de margen sobre la mesa. Si venden producto físico, no lancen nada sin calcular bien envío y comisión de pasarela. Los números primero, la emoción después.', NULL, '2026-11-09T20:09:27.626+00:00', '2026-11-10T18:09:27.627+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwb08gne002boufnjvn34jo8', 'cmwb08gn4001xoufnczor07ys', 'Terminé el programa de Marketing de Contenidos en una semana. Cinco lecciones que valen oro. Mi takeaway: constancia antes que perfección. Este mes publiqué 22 reels y dupliqué alcance sin gastar un peso en ads. Gracias ALQEMIA por un sistema tan claro.', NULL, '2026-11-10T04:09:27.626+00:00', '2026-11-10T18:09:27.626+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwb08gnd0029oufnm7cphzvw', 'cmwb08gn3001woufn4uhyiklx', 'Pregunta para los que ya escalan: en qué momento decidieron duplicar presupuesto? Llevo 3 días con un CPA estable de $4.20 y tengo miedo de romper la magia. Aportes bienvenidos, prometo devolver el favor con lo que aprenda del test.', NULL, '2026-11-10T11:09:27.625+00:00', '2026-11-10T18:09:27.626+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwb08gnd0027oufnqr23ozuj', 'cmwb08gn2001voufn9di6pipr', 'Checkpoint de la semana: cerramos la mejor semana desde que lancé la tienda. 32 órdenes y un ROAS de 3.4. La lección que me lo cambió todo fue la de escalado del Máster en Meta Ads: no toques la creativa ganadora hasta pasar las 50 conversiones. Si están en campaña, eso evita muchos dolores de cabeza.', NULL, '2026-11-10T15:09:27.624+00:00', '2026-11-10T18:09:27.625+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gns003poufn67qef5vo', 'cmwb08gnk002toufnhk1gk7yc', 'cmwb08gn3001woufn4uhyiklx', 'Ese programa es un MBA de verdad. La clase de finanzas debería ser obligatoria para todos.', '2026-11-06T04:09:27.640+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gns003noufnnnip2ny1', 'cmwb08gnj002roufn4hmmm1r4', 'cmwb08gn3001woufn4uhyiklx', 'Depende del país. Para flujo de caja rápido mira las que liquidan en 48-72h aunque cobren un poco más.', '2026-11-07T00:09:27.640+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gns003loufnhkoj7c7t', 'cmwb08gnj002poufnumcl8hsy', 'cmwb08gn6001zoufn0agonm50', '47 dólares que valen más que cualquier curso motivacional. Felicidades!', '2026-11-07T20:09:27.639+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gnq003houfnhub883uz', 'cmwb08gni002noufn0vfm51v7', 'cmwb08gn2001voufn9di6pipr', 'Bienvenida Isabela! Mi consejo: ecommerce primero si quieres vender producto, contenidos primero si quieres audiencia. Decide por el negocio, no por el gustito.', '2026-11-08T06:09:27.638+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gnr003joufn3hpr0xal', 'cmwb08gni002noufn0vfm51v7', 'cmwb08gn4001xoufnczor07ys', 'Coincido con Valeria. Y completa el perfil para que la comunidad sepa quién eres.', '2026-11-08T08:09:27.639+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gnq003foufnry5mqxg1', 'cmwb08gnh002joufnlqshc71b', 'cmwb08gn4001xoufnczor07ys', 'Te exijo los lunes. Este muro será testigo.', '2026-11-08T21:09:27.637+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gnp003boufnzuinkumg', 'cmwb08gng002houfnbh75r378', 'cmwb08gn90022oufnt8rfwd8n', 'Así se empieza. Mi primera comisión también fue sola y fue la mejor notificación del año.', '2026-11-09T04:09:27.637+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gnp003doufn4aoy97u7', 'cmwb08gng002houfnbh75r378', 'cmwb08gna0024oufnceq7kuic', 'Ánimo! Yo voy 14 días sin venta pero el punto es seguir probando. Nos vamos a comparar resultados.', '2026-11-09T06:09:27.637+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gno0039oufnsn7j8r66', 'cmwb08gnf002foufnmyq8rzs0', 'cmwb08gn70020oufny97e8zxr', 'El punto 4 es el más difícil: una sola CTA. En branding siempre quiero vender tres cosas a la vez.', '2026-11-09T17:09:27.636+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gno0037oufnh8h5jcrk', 'cmwb08gnf002doufne4c6ftat', 'cmwb08gn5001youfn2n12eo7f', 'La calculadora me reveló lo mismo con envíos. Casi lanzo regalando dinero.', '2026-11-10T00:09:27.636+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gnn0035oufntz3nfx9r', 'cmwb08gne002boufnjvn34jo8', 'cmwb08gn90023oufnf3rmtz88', 'Tu post me acaba de decidir: empiezo por contenidos. Gracias por compartir tu resultado.', '2026-11-10T08:09:27.635+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gnm0031oufne343ilgk', 'cmwb08gnd0029oufnm7cphzvw', 'cmwb08gn80021oufnncfddahr', 'Si llevas 3 días estable, sube 20% y espera 72 horas. Es lo que me funcionó con serums.', '2026-11-10T13:09:27.634+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gnm0033oufn9os9s50a', 'cmwb08gnd0029oufnm7cphzvw', 'cmwb08gn2001voufn9di6pipr', 'El miedo a romperlo es real. Pero recuerda: si funciona, se puede reconstruir. Si nunca escalas, no hay nada que reconstruir.', '2026-11-10T14:09:27.634+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gnk002voufnefjje50f', 'cmwb08gnd0027oufnqr23ozuj', 'cmwb08gn3001woufn4uhyiklx', 'Apliqué esa regla y me salvó una campaña que llevaba $800. La regla de las 50 es sagrada.', '2026-11-10T16:09:27.632+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gnl002xoufn0zu3wo39', 'cmwb08gnd0027oufnqr23ozuj', 'cmwb08gn80021oufnncfddahr', 'Ese ROAS con moda es para aplaudir. El margen de moda castiga, bien ahí.', '2026-11-10T17:09:27.632+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwb08gnm002zoufn7xq7qr19', 'cmwb08gnd0027oufnqr23ozuj', 'cmwb08gn4001xoufnczor07ys', 'Anotando la regla de las 50. Gracias por compartir el número real.', '2026-11-10T17:09:27.633+00:00');
